window.MEDLEX_HOOK_TERMS=[{"term":"Pericarditis","plain":"The protective sac around the heart is inflamed.","parts":[{"text":"peri","type":"prefix","meaning":"around"},{"text":"card","type":"root","meaning":"heart"},{"text":"itis","type":"suffix","meaning":"inflammation"}]},{"term":"Tachycardia","plain":"The heart is beating faster than expected.","parts":[{"text":"tachy","type":"prefix","meaning":"fast"},{"text":"card","type":"root","meaning":"heart"},{"text":"ia","type":"suffix","meaning":"condition"}]},{"term":"Hepatomegaly","plain":"The liver is larger than expected.","parts":[{"text":"hepat","type":"root","meaning":"liver"},{"text":"o","type":"vowel","meaning":"links word parts"},{"text":"megaly","type":"suffix","meaning":"enlargement"}]},{"term":"Hyperglycaemia","plain":"Blood glucose is higher than expected.","parts":[{"text":"hyper","type":"prefix","meaning":"excessive"},{"text":"glyc","type":"root","meaning":"sugar"},{"text":"aemia","type":"suffix","meaning":"blood condition"}]},{"term":"Haematuria","plain":"Blood is present in urine.","parts":[{"text":"haemat","type":"root","meaning":"blood"},{"text":"ur","type":"root","meaning":"urine"},{"text":"ia","type":"suffix","meaning":"condition"}]},{"term":"Gastroenteritis","plain":"The stomach and intestines are inflamed.","parts":[{"text":"gastr","type":"root","meaning":"stomach"},{"text":"o","type":"vowel","meaning":"links word parts"},{"text":"enter","type":"root","meaning":"intestine"},{"text":"itis","type":"suffix","meaning":"inflammation"}]}];
